from solution import is_happy
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if len({s[i], s[i + 1], s[i + 2]}) != 3:
            return False
    return True


# ---- concrete examples from spec ----
def test_example_single_char_is_unhappy():
    assert is_happy("a") is False


def test_example_two_chars_is_unhappy():
    assert is_happy("aa") is False


def test_example_abcd_is_happy():
    assert is_happy("abcd") is True


def test_example_aabb_is_unhappy():
    assert is_happy("aabb") is False


def test_example_adb_is_happy():
    assert is_happy("adb") is True


def test_example_xyy_is_unhappy():
    assert is_happy("xyy") is False


# ---- defect-targeting examples: first two of triple equal ----
def test_triple_first_two_equal_is_unhappy_aab():
    assert is_happy("aab") is False


def test_triple_first_two_equal_is_unhappy_aabc():
    assert is_happy("aabc") is False


def test_triple_first_two_equal_is_unhappy_ab_aab_window():
    # window "aab" at position 1
    assert is_happy("caab") is False


def test_triple_first_two_equal_longer_string():
    assert is_happy("abcdd") is False  # last window d,d? actually check happy prefix then bad
    assert is_happy("abcaab") is False
    assert is_happy("aabdef") is False


def test_triple_all_three_equal_is_unhappy():
    assert is_happy("aaa") is False
    assert is_happy("aaab") is False


def test_triple_last_two_equal_is_unhappy():
    assert is_happy("abb") is False
    assert is_happy("xyy") is False


def test_triple_first_and_third_equal_is_unhappy():
    assert is_happy("aba") is False
    assert is_happy("xyx") is False


def test_length_three_all_distinct_is_happy():
    assert is_happy("abc") is True
    assert is_happy("adb") is True
    assert is_happy("xyz") is True


# ---- boundary / length properties ----
def test_empty_string_is_unhappy():
    assert is_happy("") is False


def test_length_one_is_unhappy():
    assert is_happy("z") is False
    assert is_happy("q") is False


def test_length_two_all_combos_unhappy():
    assert is_happy("ab") is False
    assert is_happy("aa") is False
    assert is_happy("xy") is False


@given(st.text(alphabet="ab", min_size=0, max_size=5))
def test_short_strings_always_unhappy(s):
    assume(len(s) < 3)
    assert is_happy(s) is False


@given(st.text(alphabet="abc", min_size=3, max_size=8))
def test_equivalence_to_reference_model_small_alphabet(s):
    assert is_happy(s) is reference(s)


@given(st.text(alphabet="abcd", min_size=0, max_size=10))
def test_equivalence_to_reference_model_medium_alphabet(s):
    assert is_happy(s) is reference(s)


@given(st.text(alphabet="abcde", min_size=0, max_size=12))
def test_happy_implies_length_at_least_three(s):
    if is_happy(s) is True:
        assert len(s) >= 3


@given(st.text(alphabet="abcdef", min_size=3, max_size=10))
def test_happy_implies_every_window_distinct(s):
    if is_happy(s) is True:
        for i in range(len(s) - 2):
            assert s[i] != s[i + 1]
            assert s[i] != s[i + 2]
            assert s[i + 1] != s[i + 2]


@given(st.text(alphabet="ab", min_size=3, max_size=10))
def test_unhappy_if_any_window_has_equal_first_two(s):
    # if any adjacent equal pair exists, the window containing it cannot be all-distinct
    # (for len>=3, any adjacent equal pair belongs to some length-3 window)
    has_adjacent_equal = any(s[i] == s[i + 1] for i in range(len(s) - 1))
    if has_adjacent_equal:
        assert is_happy(s) is False


@given(st.text(alphabet="abc", min_size=3, max_size=10))
def test_unhappy_if_any_window_not_distinct(s):
    bad = any(len({s[i], s[i + 1], s[i + 2]}) != 3 for i in range(len(s) - 2))
    if bad:
        assert is_happy(s) is False


@given(st.lists(st.sampled_from(["a", "b", "c"]), min_size=3, max_size=8))
def test_repeated_single_char_string_is_unhappy(chars):
    s = "".join(chars)
    # all-same string of length >=3 must be unhappy
    assume(len(set(s)) == 1)
    assert is_happy(s) is False


def test_returns_bool_type():
    assert is_happy("abcd") in (True, False)
    assert type(is_happy("abcd")) is bool
    assert type(is_happy("aa")) is bool
    assert type(is_happy("")) is bool
